'use strict';
window.OperationWorkbench=(()=>{
 const base='/api/scanner/operations',h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let topicPicker=null,destinationMetadata=[];
 let accounts=[],draft={},profiles=[],preview=null,savePayload=null,saving=false,exclusionPayload=null,excludeBusy=false;
 const cards=new Map(),states={draft:'Черновик',pending:'Ожидает',queued:'В очереди',scheduled:'По расписанию',paused:'На паузе',sent:'Отправлено',invited:'Новый участник',already_member:'Уже участник',excluded:'Исключён',failed:'Ошибка',restricted:'Ограничение Telegram',uncertain:'Не подтверждено',blocked:'Ограничено',completed:'Завершено',partial:'Частичный результат',cancelled:'Отменено',removed:'Удалено',present:'На месте',not_checked:'Не проверено',missing_on_check:'Не найдено',deletion_observed:'Удаление замечено',removed_by_panel:'Удалено из панели'};
 const label=v=>states[v]||v;
 async function api(path,body){const r=await fetch(base+path,{method:body===undefined?'GET':'POST',signal:AbortSignal.timeout(60000),headers:body===undefined?{}:{'Content-Type':'application/json','X-Scanner-Request':'1'},body:body===undefined?undefined:JSON.stringify(body)});let data;try{data=await r.json();}catch{throw Error('Сервер не подтвердил результат. Обновите данные.');}if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:'Проверьте поля формы и календарь.');return data;}
 function tell(text,error=false){const el=document.querySelector('#workbench-notice');if(el){el.className=error?'ls-error':'notice';el.textContent=text;}}
 const input=(title,name,type='text',attrs='')=>`<label class="ls-field">${title}<input name="${name}" type="${type}" ${attrs}></label>`;
 const accountOptions=(global=false)=>`${global?'<option value="">Все аккаунты</option>':'<option value="">Выберите аккаунт</option>'}${accounts.map(a=>`<option value="${h(a.id)}">${h(a.label||a.id)}${a.username?' · @'+h(a.username):''} · ID ${h(a.telegram_id||'не подтверждён')}</option>`).join('')}`;
 function accountView(a){return `<details class="workbench-card" data-workbench-card="${h(a.id)}" data-identity="${h(a.telegram_id||'')}"><summary>Карточка готовности аккаунта</summary><p>Личность, соединение, пауза исходящих, внутренний дневной счётчик и очередь.</p><button type="button" class="button secondary" data-wb="readiness" data-id="${h(a.id)}">Показать карточку</button><div data-wb-card-result role="status"></div></details>`;}
 function view(tab,items){sync(items);if(tab==='exclusions')return exclusionsView();if(tab==='planner')return plannerView();return '';}
 function sync(items){accounts=items||[];for(const [key] of cards){const a=accounts.find(a=>a.id===key);if(!a)cards.delete(key);}}
 function exclusionsView(){return `<section class="panel workbench"><h2>Исключения для рассылок и приглашений</h2><p>Не писать человеку, не приглашать его или не публиковать в выбранном чате. Это отдельный список от правил антиспам-бота. Добавление исключения не переписывает старые задания; перед следующим исходящим действием список проверяется снова.</p><form id="wb-exclusion"><div class="workbench-grid"><label class="ls-field">Кого исключить<select name="subject"><option value="user">Пользователя</option><option value="chat">Группу или канал</option></select></label>${input('ID или @username','identifier','text','required maxlength="80" placeholder="@username или числовой ID"')}<label class="ls-field">Область действия<select name="account">${accountOptions(true)}</select></label>${input('Причина','reason','text','required minlength="3" maxlength="500"')}</div><p class="small muted">Для надёжной привязки используйте числовой Telegram ID. Username может измениться или перейти другому человеку.</p><button class="button" data-wb-exclusion-save>Добавить исключение</button><button type="button" class="button secondary" data-wb="reset-exclusion" hidden>Новое исключение</button></form><p id="workbench-notice" role="status" aria-live="polite"></p><p><button class="button secondary" type="button" data-wb="exclusions">Обновить список исключений</button></p><div id="wb-exclusions" role="status">Нажмите «Обновить список исключений».</div></section>`;}
 function plannerView(){return `<section class="panel workbench"><h2>Мастер кампании</h2><p>Конечный календарь и общий отчёт. Сохранение создаёт только черновики. Отправка или приглашение начнутся после отдельного подтверждения каждого задания в журнале.</p><form id="wb-plan"><h3>1. Отправитель и действие</h3><div class="workbench-grid"><label class="ls-field">Аккаунт<select name="account" required>${accountOptions()}</select></label><label class="ls-field">Тип кампании<select name="kind"><option value="post">Публикации по площадкам</option><option value="message">Личные сообщения по согласованному списку</option><option value="invite">Приглашение согласованных участников</option></select></label>${input('Название','title','text','required maxlength="100"')}</div><div data-wb-kind="post"><p><button type="button" class="button secondary" data-wb="profiles">Загрузить профили публикаций</button></p><label class="ls-field">Сохранённый профиль<select name="profile"><option value="">Выберите профиль после загрузки</option>${profileOptions()}</select></label><p class="small muted">Профили с текстом и фото создаются в разделе «Публикация». Мастер сохраняет копию выбранной версии.</p></div><h3>2. Содержание и получатели</h3><label class="ls-field" data-wb-kind="post invite">ID групп или каналов<textarea name="destinations" rows="3" placeholder="По одному отрицательному ID на строке"></textarea></label><p data-wb-kind="post invite"><button type="button" class="button secondary" data-wb="destinations">Показать площадки аккаунта</button></p><div id="wb-destinations"></div><div id="wb-topics" data-wb-kind="post"></div><label class="ls-field" data-wb-kind="message invite">Получатели @username<textarea name="users" rows="4" placeholder="До 50 согласованных получателей, по одному на строке"></textarea></label><label class="ls-field" data-wb-kind="post message">Текст<textarea name="text" rows="5" maxlength="4096"></textarea></label><p id="wb-media" class="small muted"></p><label class="ls-field" data-wb-kind="post">Основание публикации<textarea name="permission_note" rows="2" maxlength="500" placeholder="Где и с кем согласовано размещение"></textarea></label><label class="ls-field" data-wb-kind="message invite">Основание согласия получателей<textarea name="consent_note" rows="2" maxlength="500" placeholder="Как получено согласие на сообщение или приглашение"></textarea></label><h3>3. Конечный календарь и пределы</h3><div class="workbench-grid">${input('Первая дата','start_date','date','required')}${input('Последняя дата включительно, до 14 дней','end_date','date','required')}${input('Часы отправки через запятую','times','text','required placeholder="12:00 или 10:00, 15:00"')}<label class="ls-field">Часовой пояс<select name="timezone"><option value="Asia/Dubai">Дубай · Asia/Dubai</option><option value="Asia/Yekaterinburg">Екатеринбург · Asia/Yekaterinburg</option><option value="Europe/Moscow">Москва · Europe/Moscow</option><option value="UTC">UTC</option></select></label>${input('Интервал между действиями, секунд','delay_seconds','number','required min="30" max="3600" value="60"')}${input('Внутренний дневной предел аккаунта','daily_limit','number','required min="1" max="100" value="20"')}</div><p class="small muted">До 30 окон, до 3 в день. Между публикациями не менее 4 часов; окно отправки закрывается через 2 часа. Это внутренние ограничения панели, а не разрешение Telegram или правил группы. Старые паузы и дневные пределы продолжают действовать. Личные сообщения и приглашения распределяются по окнам однократно.</p><button class="button secondary" type="submit" data-wb-preview>Предпросмотр без отправки</button><div id="wb-preview" role="status"></div><label class="workbench-confirm"><input name="reviewed" type="checkbox"> Проверил отправителя, получателей и календарь. Сохранить только черновики.</label><p><button class="button" type="button" data-wb="save-plan" disabled>Сохранить кампанию как черновики</button> <button class="button secondary" type="button" data-wb="reset-plan" hidden>Новая кампания</button></p></form><p id="workbench-notice" role="status" aria-live="polite"></p><div id="wb-saved" role="status"></div><h3>Отчёты кампаний</h3><p><button type="button" class="button secondary" data-wb="plans">Загрузить кампании</button></p><div id="wb-plans"></div><div id="wb-report" role="status"></div></section>`;}
 const profileOptions=()=>profiles.filter(p=>!p.archived).map(p=>`<option value="${h(p.id)}:${h(p.revision)}">${h(p.name)} · версия ${h(p.revision)}</option>`).join('');
 function remember(){const f=document.querySelector('#wb-plan');if(f&&!savePayload){draft=Object.fromEntries(new FormData(f));delete draft.reviewed;}}
 function invalidate(){preview=null;const f=document.querySelector('#wb-plan');if(f){f.elements.reviewed.checked=false;f.querySelector('[data-wb="save-plan"]').disabled=true;f.querySelector('#wb-preview').innerHTML='';}tell('');}
 function kindFields(){const f=document.querySelector('#wb-plan');if(!f)return;const kind=f.elements.kind.value;f.querySelectorAll('[data-wb-kind]').forEach(el=>{el.hidden=!el.dataset.wbKind.split(' ').includes(kind);});const profile=profiles.find(p=>`${p.id}:${p.revision}`===f.elements.profile.value);f.querySelector('#wb-media').textContent=kind==='post'&&profile?.media?.length?`Фото из профиля: ${profile.media.length}.`:'';}
 function syncTopics(){const f=document.querySelector('#wb-plan');if(!f)return null;if(!topicPicker&&window.OperationTopics)topicPicker=window.OperationTopics.create();const ids=String(f.elements.destinations.value||'').split(/[\s,;]+/).filter(Boolean).map(Number),targets=ids.map(id=>destinationMetadata.find(d=>d.id===id)||{id,title:String(id)});topicPicker?.sync(accounts.find(a=>a.id===f.elements.account.value),targets,f.elements.kind.value);return topicPicker;}
 function drawTopics(){const el=document.querySelector('#wb-topics');if(el)el.innerHTML=syncTopics()?.view()||'';}
 function topicMappings(){const f=document.querySelector('#wb-plan');if(f?.elements.kind.value!=='post')return [];const p=syncTopics(),ids=String(f.elements.destinations.value||'').split(/[\s,;]+/).filter(Boolean).map(Number);if(ids.some(id=>destinationMetadata.some(d=>d.id===id&&d.forum===true))&&!p)throw Error('Обновите страницу, чтобы выбрать раздел группы.');return p?.mappings()||[];}
 function planSpec(){const f=document.querySelector('#wb-plan'),d=new FormData(f),a=accounts.find(a=>a.id===d.get('account'));if(!a?.telegram_id)throw Error('Выберите аккаунт с подтверждённым Telegram ID.');const kind=d.get('kind'),profile=profiles.find(p=>`${p.id}:${p.revision}`===d.get('profile')),lines=v=>String(v||'').split(/[\s,;]+/).filter(Boolean);if(kind==='post'&&!profile)throw Error('Загрузите и выберите профиль публикации.');const mappings=topicMappings();return {request_key:crypto.randomUUID(),account:a.id,telegram_id:a.telegram_id,kind,...(mappings.length?{destination_topics:mappings}:{}),title:d.get('title'),destinations:kind==='message'?[]:lines(d.get('destinations')).map(Number),users:kind==='post'?[]:lines(d.get('users')),text:kind==='invite'?'':d.get('text')||'',media:kind==='post'?profile.media||[]:[],permission_note:kind==='post'?d.get('permission_note')||'':'',consent_note:kind==='post'?'':d.get('consent_note')||'',delay_seconds:Number(d.get('delay_seconds')),daily_limit:Number(d.get('daily_limit')),campaign_id:kind==='post'?profile.id:null,campaign_revision:kind==='post'?profile.revision:null,timezone:d.get('timezone'),start_date:d.get('start_date'),end_date:d.get('end_date'),times:lines(d.get('times'))};}
 function fingerprint(value){const {request_key,...rest}=value;return JSON.stringify(rest);}
 function mount(items){sync(items);const f=document.querySelector('#wb-plan');if(f){for(const [key,value] of Object.entries(draft)){if(f.elements[key])f.elements[key].value=value;}kindFields();drawTopics();if(savePayload)freezePlan();else if(preview){const a=accounts.find(a=>a.id===preview.spec.account);if(!a||a.telegram_id!==preview.spec.telegram_id)invalidate();else renderPreview(preview.result);}}document.querySelectorAll('[data-workbench-card]').forEach(el=>{const row=cards.get(el.dataset.workbenchCard);if(row&&row.identity===Number(el.dataset.identity))el.querySelector('[data-wb-card-result]').innerHTML=row.html;});}
 function renderPreview(p){const el=document.querySelector('#wb-preview');if(!el)return;el.innerHTML=`<h3>Проверка календаря</h3><p>Окон: ${p.slots.length}. Действий до проверки Telegram: ${h(p.total_items)}.</p><ol>${p.slots.map(s=>`<li>${h(s.local)} · ${h(s.items)} получателей/площадок</li>`).join('')}</ol>${preview?.spec?.destination_topics?.length?`<h4>Разделы публикации</h4><ul>${(topicPicker?.preview(destinationMetadata.filter(d=>preview.spec.destinations.includes(d.id)))||[]).filter(d=>d.forum).map(d=>`<li>${h(d.title)} · ${d.topic_id===1?h(window.OperationTopics?.label?.(d.topic_title,d.topic_id)||'Общий раздел (General), ID 1'):h(d.topic_title||'Раздел не подтверждён')+(d.topic_id?' · #'+h(d.topic_id):'')}</li>`).join('')}</ul>`:''}${p.known_exclusions.length?`<p>Найдены исключения: ${p.known_exclusions.map(x=>h(x.identifier)+' — '+h(x.reason)).join('; ')}. При сохранении они будут отмечены как исключённые.</p>`:''}<p>${h(p.note)}</p>`;}
 function freezePlan(){const f=document.querySelector('#wb-plan');if(!f)return;f.querySelectorAll('input,select,textarea,[data-wb-preview]').forEach(el=>el.disabled=true);const b=f.querySelector('[data-wb="save-plan"]');b.disabled=false;b.textContent='Проверить сохранение той же кампании';f.querySelector('[data-wb="reset-plan"]').hidden=false;}
 async function loadExclusions(){const r=await api('/exclusions'),el=document.querySelector('#wb-exclusions');if(!el)return;el.innerHTML=r.items.length?`<div class="workbench-list">${r.items.map(x=>`<article><strong>${x.subject==='user'?'Пользователь':'Площадка'}: ${h(x.identifier)}</strong><p>${h(x.reason)}</p><p class="small">${x.account?'Аккаунт '+h(x.account)+' · ID '+h(x.telegram_id):'Все аккаунты'} · ${x.active?'Действует':'Отключено'} · версия ${h(x.revision)}</p>${x.active?`<button type="button" class="button secondary" data-wb="disable-exclusion" data-id="${x.id}" data-revision="${x.revision}">Отключить исключение #${x.id}</button>`:''}</article>`).join('')}</div>`:'Исключений пока нет.';}
 async function showReport(id){const r=await api('/plans/'+id),el=document.querySelector('#wb-report');if(!el)return;el.innerHTML=`<h3>${h(r.title)}</h3><p>Аккаунт: ${h(r.account)} · Telegram ID ${h(r.telegram_id)}</p><dl class="workbench-counts">${Object.entries(r.counts).map(([k,v])=>`<div><dt>${h(label(k))}</dt><dd>${h(v)}</dd></div>`).join('')}</dl><p>Ответы в группах с подтверждённой связью: ${h(r.group_replies)}.</p>${Object.keys(r.presence).length?`<p>Последние наблюдения за публикациями: ${Object.entries(r.presence).map(([k,v])=>h(label(k))+': '+h(v)).join('; ')}.</p>`:''}<p>${h(r.note)}</p><a class="button secondary" href="${base}/plans/${Number(id)}/report" download>Скачать CSV</a><ol>${r.jobs.map(j=>`<li>Задание #${h(j.id)} · ${h(label(j.state))} · ${h(new Date(j.not_before*1000).toLocaleString('ru-RU'))}</li>`).join('')}</ol><p><a href="#operations">Аккаунты и журнал заданий</a></p>`;}
 document.addEventListener('input',e=>{if(e.target.closest('#wb-plan')){if(savePayload||e.target.name==='reviewed')return;if(e.target.hasAttribute('data-op-topic-input'))syncTopics()?.input(Number(e.target.dataset.opTopicInput),e.target.value);invalidate();remember();if(e.target.name==='destinations')drawTopics();}});
 document.addEventListener('change',e=>{const f=e.target.closest('#wb-plan');if(!f)return;if(e.target.name==='reviewed'){const b=f.querySelector('[data-wb="save-plan"]');b.disabled=!preview||!e.target.checked;return;}if(savePayload)return;if(e.target.name==='profile'){const p=profiles.find(p=>`${p.id}:${p.revision}`===e.target.value);if(p){f.elements.text.value=p.text||'';f.elements.delay_seconds.value=p.delay_seconds;f.elements.daily_limit.value=p.daily_limit;}}if(e.target.name==='account'){destinationMetadata=[];document.querySelector('#wb-destinations').innerHTML='';}invalidate();remember();kindFields();if(['account','kind'].includes(e.target.name))drawTopics();});
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-op-topic-check]');if(!b||!b.closest('#wb-plan')||savePayload)return;e.preventDefault();e.stopImmediatePropagation();const f=b.closest('#wb-plan'),picker=syncTopics();if(!picker)return;invalidate();const pending=picker.check(Number(b.dataset.opTopicCheck),api,accounts.find(a=>a.id===f.elements.account.value));drawTopics();await pending;drawTopics();},true);
 document.addEventListener('submit',async e=>{const f=e.target;if(!['wb-plan','wb-exclusion'].includes(f.id))return;e.preventDefault();e.stopImmediatePropagation();try{if(f.id==='wb-plan'){if(savePayload||saving)return;remember();const spec=planSpec(),stamp=fingerprint(spec);tell('Проверяем календарь без обращения к Telegram…');const r=await api('/plans/preview',spec);if(!f.isConnected||fingerprint(planSpec())!==stamp)return;preview={spec,result:r};renderPreview(r);tell('Предпросмотр готов. Проверьте его и подтвердите сохранение черновиков.');}else{if(excludeBusy)return;excludeBusy=true;const b=f.querySelector('[data-wb-exclusion-save]');b.disabled=true;try{if(!exclusionPayload){const d=new FormData(f),a=accounts.find(a=>a.id===d.get('account'));if(d.get('account')&&!a?.telegram_id)throw Error('У аккаунта не подтверждён Telegram ID.');exclusionPayload={request_key:crypto.randomUUID(),subject:d.get('subject'),identifier:d.get('identifier'),reason:d.get('reason'),account:a?.id||null,telegram_id:a?.telegram_id||null};}await api('/exclusions',exclusionPayload);exclusionPayload=null;f.reset();f.querySelectorAll('input,select').forEach(el=>el.disabled=false);b.textContent='Добавить исключение';tell('Исключение сохранено. Задания не запускались.');await loadExclusions();}catch(err){if(exclusionPayload){f.querySelectorAll('input,select').forEach(el=>el.disabled=true);b.textContent='Проверить сохранение того же исключения';f.querySelector('[data-wb="reset-exclusion"]').hidden=false;}throw err;}finally{excludeBusy=false;b.disabled=false;}}}catch(err){tell(err.message,true);}},true);
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-wb]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(b.disabled)return;b.disabled=true;try{const action=b.dataset.wb,id=b.dataset.id;
  if(action==='readiness'){const el=b.closest('[data-workbench-card]'),identity=Number(el.dataset.identity),r=await api('/accounts/'+encodeURIComponent(id)+'/readiness');if(!el.isConnected||Number(el.dataset.identity)!==identity||r.telegram_id!==identity)throw Error('Личность аккаунта изменилась. Обновите панель.');const html=`<p><strong>${r.readiness==='ready'?'Готов по данным панели':'Есть ограничения'}</strong></p><p>ID ${h(r.telegram_id)} · Соединение: ${r.connected?'подключено':'отключено'} · Личность: ${r.identity_confirmed?'подтверждена':'не подтверждена'}.</p><p>Исходящие: ${r.outbound_enabled?'разрешены в панели':'на паузе'}. Ожидание: ${h(r.cooldown_seconds)} сек.</p><p>Соединение: ${h(r.proxy.mode)}${r.proxy.address?' · '+h(r.proxy.address)+':'+h(r.proxy.port):''}.</p>${r.budget?`<p>Сегодня UTC: использовано ${h(r.budget.account_count_today)}, предел панели ${h(r.budget.effective_daily_limit)}, осталось ${h(r.budget.remaining_today)}.</p>`:''}<p>Задания: ${Object.entries(r.jobs).map(([k,v])=>h(label(k))+': '+h(v)).join('; ')||'нет'}.</p><p class="small muted">${h(r.note)} Проверено: ${h(r.checked_at)}.</p>`;cards.set(id,{identity,html});el.querySelector('[data-wb-card-result]').innerHTML=html;
  }else if(action==='profiles'){const r=await api('/campaigns');remember();profiles=r.campaigns;const f=document.querySelector('#wb-plan');if(f){f.elements.profile.innerHTML='<option value="">Выберите профиль</option>'+profileOptions();f.elements.profile.value=draft.profile||'';invalidate();tell('Профили загружены. Выберите нужную версию.');}
  }else if(action==='destinations'){const f=document.querySelector('#wb-plan'),aid=f.elements.account.value;if(!aid)throw Error('Выберите аккаунт.');const r=await api('/accounts/'+encodeURIComponent(aid)+'/destinations');if(!f.isConnected||f.elements.account.value!==aid)return;destinationMetadata=r.destinations;drawTopics();invalidate();document.querySelector('#wb-destinations').innerHTML=`<p class="small">Скопируйте ID нужных площадок в поле выше.</p><ul>${r.destinations.map(d=>`<li>${h(d.title)} · <code>${h(d.id)}</code></li>`).join('')}</ul>`;
  }else if(action==='save-plan'){if(saving)return;const f=document.querySelector('#wb-plan');if(!savePayload){if(!preview||!f.elements.reviewed.checked)throw Error('Проверьте предпросмотр и отметьте подтверждение.');const current=planSpec();if(fingerprint(current)!==fingerprint(preview.spec))throw Error('Форма изменилась. Повторите предпросмотр.');remember();savePayload=preview.spec;}saving=true;freezePlan();b.disabled=true;try{tell('Проверяем получателей и сохраняем только черновики…');const r=await api('/plans',savePayload);document.querySelector('#wb-saved').innerHTML=`<p>Кампания #${h(r.id)} сохранена. Заданий: ${r.jobs.length}. Ничего не запущено.</p><button type="button" class="button secondary" data-wb="report" data-id="${r.id}">Показать отчёт кампании</button>`;b.hidden=true;tell('Черновики готовы. Запуск каждого задания подтверждается отдельно в журнале.');}finally{saving=false;}
  }else if(action==='reset-plan'){if(saving)return;savePayload=null;draft={};preview=null;destinationMetadata=[];topicPicker=null;const el=document.querySelector('#op-body');if(el){el.innerHTML=plannerView();mount(accounts);}
  }else if(action==='reset-exclusion'){exclusionPayload=null;const f=document.querySelector('#wb-exclusion');f.reset();f.querySelectorAll('input,select,button').forEach(el=>el.disabled=false);f.querySelector('[data-wb-exclusion-save]').textContent='Добавить исключение';b.hidden=true;tell('Можно добавить новое исключение. Ранее отправленный запрос проверьте в списке.');
  }else if(action==='exclusions')await loadExclusions();
  else if(action==='disable-exclusion'){if(!confirm('Отключить это исключение? Новые действия для получателя снова смогут пройти проверку списка.'))return;await api('/exclusions/'+id+'/disable',{revision:Number(b.dataset.revision),confirmed:true});await loadExclusions();tell('Исключение отключено. Задания не запускались.');}
  else if(action==='plans'){const r=await api('/plans'),el=document.querySelector('#wb-plans');if(el)el.innerHTML=r.items.length?r.items.map(p=>`<p><button class="button secondary" type="button" data-wb="report" data-id="${p.id}">#${p.id} · ${h(p.title)}</button></p>`).join(''):'Кампаний, созданных мастером, пока нет. Старые задания доступны в журнале.';}
  else if(action==='report')await showReport(Number(id));
 }catch(err){tell(err.message,true);if(b.dataset.wb==='readiness'){const el=b.closest('[data-workbench-card]');if(el)el.querySelector('[data-wb-card-result]').textContent=err.message;}}finally{b.disabled=false;}},true);
 return {view,mount,accountView};
})();
